import pandas as pd, numpy as np, math, sys
d=pd.read_csv(sys.argv[1] if len(sys.argv)>1 else 'pred.csv')
d['ex']=d.number_set.astype(str).apply(lambda s:[int(x) for x in s.split(',')])
d['isex']=[t in e for t,e in zip(d.target,d.ex)]
p2={1,2,4,8,16,32,64}; p3={1,3,9,27,81}; sq={i*i for i in range(1,11)}; cu={1,8,27,64}
pr={n for n in range(2,101) if all(n%k for k in range(2,int(n**.5)+1))}
def allin(S): return d.ex.apply(lambda e: len(e)>=2 and all(x in S for x in e))
for name,S in [('pow2',p2),('pow3',p3),('sq',sq),('cube',cu),('prime',pr)]:
    m=allin(S)&~d.isex
    sub=d[m]; tin=sub.target.isin(S)
    print(name, 'sets',sub.number_set.unique()[:12])
    for k,g in sub.groupby(tin): print('  target in',k,len(g),'obs %.3f pred %.3f'%(g.rating.mean(),g.p.mean()))
# all-example check for primes on all sets
sub=d[~d.isex]
for name,S in [('pow2',p2),('sq',sq),('prime',pr)]:
    g=sub.groupby(sub.target.isin(S)); print(name,'any set',[(k,len(x),round(x.rating.mean()-x.p.mean(),3)) for k,x in g])
